int main() {
    int length;
    std::cin >> length;
    std::string text;
    std::cin >> text;
    for (auto &c : text) c = tolower(c);
    int maxSegment = -1;
    int wordCount = 0;
    int parenthesesLevel = 0;
    int underscoreSeq = 0;
    for (int i = 0; i < length; i++) {
        char ch = text[i];
        if (ch == '(') {
            parenthesesLevel++;
            underscoreSeq = 0;
        } else if (ch == ')') {
            if (parenthesesLevel == 1 && underscoreSeq != 0) wordCount++;
            parenthesesLevel--;
            underscoreSeq = 0;
        } else if (ch == '_') {
            if (parenthesesLevel == 1 && underscoreSeq != 0) wordCount++;
            underscoreSeq = 0;
        } else {
            underscoreSeq++;
        }
        if (parenthesesLevel == 0) {
            maxSegment = std::max(underscoreSeq, maxSegment);
        }
    }
    std::cout << maxSegment << " " << wordCount << std::endl;
    return 0;
}
